package com.bank.report.mapper;

import java.lang.reflect.Field;
import java.util.*;
import java.util.logging.*;

// Reflectively populates any object's private fields from a value map.
// PERFORMANCE: cache Field handles per class, and setAccessible(true) ONCE,
// so we don't pay lookup + access-check costs on every row.
public class ReflectiveMapper {
    private static final Logger log = Logger.getLogger(ReflectiveMapper.class.getName());
    private final Map<Class<?>, Field[]> fieldCache = new HashMap<>();

    public <T> T populate(Class<T> type, Map<String, Object> values) throws Exception {
        T instance = type.getDeclaredConstructor().newInstance();
        Field[] fields = fieldCache.computeIfAbsent(type, this::resolveFields);  // cached lookup
        for (Field f : fields) {
            if (values.containsKey(f.getName())) {
                f.set(instance, values.get(f.getName()));  // fast: access check already suppressed
            }
        }
        return instance;
    }

    private Field[] resolveFields(Class<?> type) {
        Field[] fields = type.getDeclaredFields();
        for (Field f : fields) {
            // Requires the field's package to be OPEN under JPMS, or this throws.
            f.setAccessible(true);   // suppress per-call access checks (done once, cached)
        }
        log.fine(() -> "Resolved + cached " + fields.length + " fields for " + type.getSimpleName());
        return fields;
    }
}
