package com.bank.report;

import com.bank.report.mapper.ReflectiveMapper;
import com.bank.report.model.StatementReport;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class ReflectionDemo {
    private static final Logger log = Logger.getLogger(ReflectionDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        var mapper = new ReflectiveMapper();

        var rajesh = mapper.populate(StatementReport.class, Map.of(
                "accountId", "SAV2001", "holderName", "Rajesh",
                "closingBalance", new BigDecimal("1000000.00")));
        var priya = mapper.populate(StatementReport.class, Map.of(
                "accountId", "CUR3001", "holderName", "Priya",
                "closingBalance", new BigDecimal("250000.00")));

        log.info(() -> "Report: " + rajesh.getAccountId() + " " + rajesh.getHolderName()
                + " Rs." + rajesh.getClosingBalance());
        log.info(() -> "Report: " + priya.getAccountId() + " " + priya.getHolderName()
                + " Rs." + priya.getClosingBalance());
        log.info("Private fields populated via cached reflection (opens made it legal under JPMS)");
    }
}
